-- pay_common_amount_facts_valid(jsonb)
CREATE OR REPLACE FUNCTION public.pay_common_amount_facts_valid(v jsonb)
 RETURNS boolean
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE x jsonb;
BEGIN
  IF v IS NULL THEN RETURN true; END IF;
  IF jsonb_typeof(v) <> 'array' OR jsonb_array_length(v)>128 THEN RETURN false; END IF;
